import sys,json
from pathlib import Path
P=Path(__file__).resolve().parent;sys.path.insert(0,str(P.parent/'match-r01'));from bootstrap import call
names=['30_MENU09_Media_Review','31_MENU09_Media_Collection','32_MENU09_Media_Shop','33_MENU09_Media_Match'];audit=[]
for name in names:
 call('await penpot.openPage(storage.media09.pages['+json.dumps(name)+']);return penpot.currentPage.name')
 code="""const p=penpot.currentPage,S=storage.match09,M=storage.media09;const walk=s=>[s,...(s.children||[]).flatMap(walk)];const sourceName=p.name.includes('Collection')?'25_MENU09_Collection':p.name.includes('Shop')?'26_MENU09_Shop':p.name.includes('Match')?'29_MENU09_Match':'23_MENU09_Review';const source=penpotUtils.getPageByName(sourceName);const originals=Object.fromEntries(source.root.children.map(b=>[b.getPluginData('menu09-key'),b]));const boards=[];for(const b of p.root.children){const key=b.getPluginData('menu09-key'),base=originals[key];const changed=!base||S.hash(S.snap(b))!==S.hash(S.snap(base));b.setPluginData('menu09-approval',changed?'review-pending-media':'approved-layout-copy');if(changed){b.setPluginData('menu09-approved-revision','');b.setPluginData('menu09-approval-evidence','media-assets-r01 제작·반영; 새 미디어 사용자 승인 미기록. 기존 레이아웃 승인은 source-page와 layout-approval-reference 참조.');}if(key==='shop-character-myo-ryung-light-video'){const play=b.children.find(s=>s.name==='MEDIA / modal play');if(play){for(const i of [...play.interactions||[]])play.removeInteraction(i);play.addInteraction('click',{type:'open-url',url:'http://127.0.0.1:4471/?slot=VIDEO%2Fmyo-ryung%2Flight'});}}const a=walk(b);boards.push({key,id:b.id,name:b.name,w:b.width,h:b.height,status:b.getPluginData('menu09-approval'),shapeHash:S.hash(S.snap(b)),texts:a.filter(s=>s.type==='text').map(s=>({id:s.id,name:s.name,text:s.characters,hidden:s.hidden,x:s.parentX,y:s.parentY,w:s.width,h:s.height})),media:a.filter(s=>s.getPluginData('menu09-image-slot')||s.getPluginData('menu09-video-slot')).map(s=>({id:s.id,slot:s.getPluginData('menu09-image-slot')||s.getPluginData('menu09-video-slot'),mediaId:s.fills?.[0]?.fillImage?.id,x:s.parentX,y:s.parentY,w:s.width,h:s.height})),links:a.flatMap(s=>(s.interactions||[]).map(i=>({shape:s.id,name:s.name,trigger:i.trigger,type:i.action.type,dest:i.action.destination?.id,url:i.action.url})))})}return {name:p.name,id:p.id,boards};"""
 r=call(code);audit.append(r);print(name,len(r['boards']),sum(b['status']=='review-pending-media' for b in r['boards']),flush=True)
(P/'penpot-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2));(P/'placements.json').write_text(json.dumps(call('return storage.media09.placements'),ensure_ascii=False,indent=2))
expected={r['slot'] for r in json.loads((P/'asset-map.json').read_text())['assets']};actual={m['slot'] for p in audit for b in p['boards'] for m in b['media']};assert expected<=actual,(expected-actual)
print('All 29 exact slots placed')
